{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "context_heading",
        "context_stack",
        "hotels_heading",
        "drury_card",
        "holidayinn_card",
        "springhill_card",
        "disney_allstar_card",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Walt Disney World Family Stays",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Planning a family trip to Walt Disney World in Orlando for March 2025? Here are some highly-rated hotel options that offer family-friendly amenities, shuttle service to the parks, and a pool, all within your specified budget.",
        "variant": "body"
      },
      "children": []
    },
    "context_heading": {
      "type": "Text",
      "props": {
        "text": "Context for Recommendations",
        "variant": "h3"
      },
      "children": []
    },
    "context_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "context_children_age",
        "context_near_disney",
        "context_pricing"
      ]
    },
    "context_children_age": {
      "type": "Text",
      "props": {
        "text": "Children's Age: Assumed children are under 12 for general hotel occupancy and amenities.",
        "variant": "body"
      },
      "children": []
    },
    "context_near_disney": {
      "type": "Text",
      "props": {
        "text": "\"Near Walt Disney World\": Hotels are located within a convenient shuttle or short driving distance to the parks.",
        "variant": "body"
      },
      "children": []
    },
    "context_pricing": {
      "type": "Text",
      "props": {
        "text": "Pricing: Estimated nightly rates for March 10-14, 2025, are subject to change and may not include all taxes and resort fees. Actual prices may vary based on booking time and specific room types.",
        "variant": "body"
      },
      "children": []
    },
    "hotels_heading": {
      "type": "Text",
      "props": {
        "text": "Recommended Hotels for Your Orlando Trip",
        "variant": "h3"
      },
      "children": []
    },
    "drury_card": {
      "type": "Card",
      "props": {},
      "children": [
        "drury_header_stack",
        "drury_summary",
        "drury_features_label",
        "drury_features",
        "drury_button"
      ]
    },
    "drury_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "drury_icon",
        "drury_name"
      ]
    },
    "drury_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/house.svg"
      },
      "children": []
    },
    "drury_name": {
      "type": "Text",
      "props": {
        "text": "Drury Plaza Hotel Orlando - Disney Springs Area",
        "variant": "h3"
      },
      "children": []
    },
    "drury_summary": {
      "type": "Text",
      "props": {
        "text": "A top-rated, newer hotel offering excellent value with complimentary hot breakfast and evening reception, plus a dedicated shuttle to Disney parks.",
        "variant": "body"
      },
      "children": []
    },
    "drury_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "drury_features": {
      "type": "Text",
      "props": {
        "text": "Free Hot Breakfast & Evening Reception, Resort-style Pool, Walkable to Disney Springs via pedestrian bridge.",
        "variant": "body"
      },
      "children": []
    },
    "drury_button": {
      "type": "Button",
      "props": {
        "label": "Book Drury Plaza"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.druryhotels.com/locations/orlando-fl/drury-plaza-hotel-orlando-disney-springs-area"
          }
        }
      },
      "children": []
    },
    "holidayinn_card": {
      "type": "Card",
      "props": {},
      "children": [
        "holidayinn_header_stack",
        "holidayinn_summary",
        "holidayinn_features_label",
        "holidayinn_features",
        "holidayinn_button"
      ]
    },
    "holidayinn_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "holidayinn_icon",
        "holidayinn_name"
      ]
    },
    "holidayinn_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/water.svg"
      },
      "children": []
    },
    "holidayinn_name": {
      "type": "Text",
      "props": {
        "text": "Holiday Inn Resort Orlando Suites – Waterpark",
        "variant": "h3"
      },
      "children": []
    },
    "holidayinn_summary": {
      "type": "Text",
      "props": {
        "text": "An all-suite resort designed for families, featuring a full waterpark, various activities, and complimentary shuttle service to Walt Disney World.",
        "variant": "body"
      },
      "children": []
    },
    "holidayinn_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "holidayinn_features": {
      "type": "Text",
      "props": {
        "text": "On-site Waterpark & Kids' Activities, Spacious Family Suites, Arcade & Dining Options.",
        "variant": "body"
      },
      "children": []
    },
    "holidayinn_button": {
      "type": "Button",
      "props": {
        "label": "Book Holiday Inn Waterpark"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ihg.com/holidayinnresorts/hotels/us/en/orlando/mcofr/hoteldetail"
          }
        }
      },
      "children": []
    },
    "springhill_card": {
      "type": "Card",
      "props": {},
