        "springhill_name"
      ]
    },
    "springhill_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg"
      },
      "children": []
    },
    "springhill_name": {
      "type": "Text",
      "props": {
        "text": "SpringHill Suites by Marriott Orlando at Flamingo Crossings Town Center",
        "variant": "h3"
      },
      "children": []
    },
    "springhill_summary": {
      "type": "Text",
      "props": {
        "text": "Modern and comfortable suites with complimentary breakfast, conveniently located near Disney's Animal Kingdom with shuttle service.",
        "variant": "body"
