    "springhill_features_label": {
      "type": "Text",
      "props": {
        "text": "Key Features:",
        "variant": "label"
      },
      "children": []
    },
    "springhill_features": {
      "type": "Text",
      "props": {
        "text": "Free Breakfast, Outdoor Pool & Splash Pad, Fitness Center, Suites with Separate Living Areas.",
        "variant": "body"
      },
      "children": []
    },
    "springhill_button": {
      "type": "Button",
      "props": {
        "label": "Book SpringHill Suites"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.marriott.com/en-us/hotels/mcofr-springhill-suites-orlando-at-flamingo-crossings-town-center/overview/"
          }
        }
      },
      "children": []
