      "type": "Text",
      "props": {
        "text": "Disney's All-Star Movies Resort",
        "variant": "h3"
      },
      "children": []
    },
    "disney_allstar_summary": {
      "type": "Text",
      "props": {
        "text": "An official Walt Disney World Resort hotel offering themed rooms, multiple pools, and complimentary transportation to all Disney parks.",
        "variant": "body"
      },
      "children": []
